  (* [comment removed for export] *)
  Lemma pn_F3 : forall regs m,
    rdn SEGS m (Z_to_bv 64 0x1125c8) 8 = Some (Z_to_le_bytes 8 0x1137b8) -> rdn SEGS m (Z_to_bv 64 0x1137b8) 4 = Some (Z_to_le_bytes 4 3) ->
    exists regs',
      msteps SEGS (mkst regs (0x6c7ac : word) m rom) (mkst regs' (0x6311c : word) m rom)
      /\ getr regs' 10 = Z_to_bv 64 0x1b954 /\ getr regs' 11 = Z_to_bv 64 0x13c65 /\ getr regs' 12 = Z_to_bv 64 0 /\ getr regs' 1 = Z_to_bv 64 0x6c7d8
      /\ regs_agree (fun r => In r [1; 10; 11; 12]%list) regs regs'.
Proof.
